'use strict';
const fs = require('fs');
const path = require('path');
const DIR = __dirname;

const GLOBAL_KEYS = ['HTMLElement','HTMLInputElement','HTMLButtonElement','HTMLFormElement','Node','Element','Event','CustomEvent','MouseEvent','KeyboardEvent','FocusEvent','InputEvent','SVGElement','getComputedStyle','requestAnimationFrame','cancelAnimationFrame','MutationObserver','HTMLIFrameElement','Text','Comment','DocumentFragment'];
const BOUND_KEYS = ['getComputedStyle','requestAnimationFrame','cancelAnimationFrame'];

function setGlobal(k, v) {
  try {
    Object.defineProperty(globalThis, k, { value: v, configurable: true, writable: true });
  } catch (e) {
    try { globalThis[k] = v; } catch (e2) { /* ignore */ }
  }
}

function installGlobals(win) {
  setGlobal('window', win);
  setGlobal('document', win.document);
  setGlobal('navigator', win.navigator);
  for (const k of GLOBAL_KEYS) {
    if (win[k] === undefined) continue;
    const v = BOUND_KEYS.includes(k) ? win[k].bind(win) : win[k];
    setGlobal(k, v);
  }
  globalThis.IS_REACT_ACT_ENVIRONMENT = true;
}

function compile(src, fileName) {
  const ts = require('typescript');
  const out = ts.transpileModule(src, {
    fileName: fileName,
    compilerOptions: {
      jsx: ts.JsxEmit.React,
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2019,
      esModuleInterop: true,
      allowJs: true
    }
  });
  return out.outputText;
}

function evalModule(code, localRequire) {
  const mod = { exports: {} };
  const fn = new Function('require', 'module', 'exports', code);
  fn(localRequire, mod, mod.exports);
  return mod.exports;
}

function findSignIn(container) {
  const buttons = Array.from(container.querySelectorAll('button'));
  const btn = buttons.find((b) => (b.textContent || '').trim() === 'Sign In');
  if (!btn) throw new Error('Sign In button not found');
  return btn;
}

function isDialogVisible(doc) {
  return !!doc.querySelector('[role="dialog"]');
}

async function runCase(ctx, input) {
  const { doc, React, ReactDOMClient, act, loginSrc, appSrc } = ctx;
  doc.body.innerHTML = '<div id="root"></div>';
  const container = doc.getElementById('root');

  const loginExports = evalModule(loginSrc, (name) => require(name));
  const appExports = evalModule(appSrc, (name) => (name === './LoginModal' ? loginExports : require(name)));
  const AppComponent = appExports.default;

  const actions = input && input.actions;
  if (!Array.isArray(actions)) throw new Error('input.actions must be an array');

  const root = ReactDOMClient.createRoot(container);
  const visible = [];
  try {
    await act(async () => { root.render(React.createElement(AppComponent)); });
    for (const a of actions) {
      if (a === 'click_sign_in') {
        const btn = findSignIn(container);
        await act(async () => { btn.click(); });
      } else if (a === 'wait') {
        await act(async () => { await new Promise((r) => setTimeout(r, 0)); });
      } else {
        throw new Error('unknown action: ' + String(a));
      }
      visible.push(isDialogVisible(doc));
    }
  } finally {
    try { await act(async () => { root.unmount(); }); } catch (e) { /* ignore cleanup errors */ }
    doc.body.innerHTML = '';
  }
  return visible;
}

async function main() {
  let inputs;
  try {
    inputs = JSON.parse(fs.readFileSync(path.join(DIR, 'inputs.json'), 'utf8'));
  } catch (e) {
    return { results: [], harness_error: 'cannot read inputs.json: ' + e.message };
  }
  if (!Array.isArray(inputs)) return { results: [], harness_error: 'inputs.json must be an array' };

  let loginSrc, appSrc;
  try {
    loginSrc = compile(fs.readFileSync(path.join(DIR, 'block-1.txt'), 'utf8'), 'LoginModal.jsx');
    appSrc = compile(fs.readFileSync(path.join(DIR, 'block-2.txt'), 'utf8'), 'App.jsx');
  } catch (e) {
    return { results: [], harness_error: 'cannot load candidate source: ' + e.message };
  }

  let ctx;
  try {
    const { JSDOM } = require('jsdom');
    const dom = new JSDOM('<!doctype html><html><body></body></html>', { pretendToBeVisual: true, url: 'http://localhost/' });
    installGlobals(dom.window);
    const React = require('react');
    const ReactDOMClient = require('react-dom/client');
    const { act } = require('react-dom/test-utils');
    ctx = { dom, doc: dom.window.document, React, ReactDOMClient, act, loginSrc, appSrc };
  } catch (e) {
    return { results: [], harness_error: 'infrastructure load failure: ' + ((e && e.message) || String(e)) };
  }

  const results = [];
  for (const item of inputs) {
    const id = item && item.id;
    try {
      const actual = await runCase(ctx, item && item.input);
      results.push({ id: id, actual: actual });
    } catch (e) {
      results.push({ id: id, error: String((e && e.message) || e) });
    }
  }
  try { ctx.dom.window.close(); } catch (e) { /* ignore */ }
  return { results: results };
}

function finish(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n', () => process.exit(0));
}

(async () => {
  const saved = { log: console.log, error: console.error, warn: console.warn, info: console.info, debug: console.debug };
  const silence = () => {};
  for (const k of Object.keys(saved)) console[k] = silence;
  let out;
  try {
    out = await main();
  } catch (e) {
    out = { results: [], harness_error: 'harness failure: ' + ((e && e.message) || String(e)) };
  }
  for (const k of Object.keys(saved)) console[k] = saved[k];
  finish(out);
})();

const fs = require('fs');
const path = require('path');
const realWrite = process.stdout.write.bind(process.stdout);
const noop = () => {};
console.log = console.info = console.warn = console.error = console.debug = noop;

function emit(obj) { realWrite(JSON.stringify(obj) + '\n'); }

function setup() {
  const { JSDOM } = require('jsdom');
  const dom = new JSDOM('<!doctype html><html><body></body></html>', { pretendToBeVisual: true, url: 'http://localhost/' });
  const w = dom.window;
  for (const key of Object.getOwnPropertyNames(w)) {
    if (!(key in globalThis)) { try { globalThis[key] = w[key]; } catch (e) {} }
  }
  globalThis.window = w;
  globalThis.document = w.document;
  globalThis.navigator = w.navigator;
  globalThis.IS_REACT_ACT_ENVIRONMENT = true;

  const ts = require('typescript');
  const srcDir = path.join(__dirname, 'app');
  fs.mkdirSync(srcDir, { recursive: true });
  const compile = (blockFile, outName) => {
    const src = fs.readFileSync(path.join(__dirname, blockFile), 'utf8');
    const res = ts.transpileModule(src, {
      fileName: outName.replace(/\.js$/, '.jsx'),
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2019,
        jsx: ts.JsxEmit.React,
        esModuleInterop: true,
        allowJs: true
      }
    });
    fs.writeFileSync(path.join(srcDir, outName), res.outputText);
  };
  compile('block-3.txt', 'LoginModal.js');
  compile('block-2.txt', 'App.js');

  const React = require('react');
  const ReactDOM = require('react-dom/client');
  const { act } = require('react-dom/test-utils');
  const mod = require(path.join(srcDir, 'App.js'));
  const App = mod.default || mod;
  return { w, React, ReactDOM, act, App };
}

function findSignIn(doc) {
  return Array.from(doc.querySelectorAll('button')).find((b) => (b.textContent || '').trim() === 'Sign In') || null;
}

function dialogVisible(doc) {
  const el = doc.querySelector('[role=dialog]');
  if (!el) return false;
  for (let n = el; n && n.nodeType === 1; n = n.parentElement) {
    if (n.hidden || (n.style && (n.style.display === 'none' || n.style.visibility === 'hidden'))) return false;
  }
  return true;
}

function runCase(ctx, input) {
  const { w, React, ReactDOM, act, App } = ctx;
  const doc = w.document;
  if (!input || !Array.isArray(input.actions)) throw new Error('invalid input: expected object with actions array');
  const container = doc.createElement('div');
  doc.body.appendChild(container);
  const root = ReactDOM.createRoot(container);
  const seen = [];
  try {
    act(() => { root.render(React.createElement(App)); });
    for (const action of input.actions) {
      if (action === 'click_sign_in') {
        const btn = findSignIn(doc);
        if (!btn) throw new Error('Sign In button not found');
        act(() => { btn.dispatchEvent(new w.MouseEvent('click', { bubbles: true, cancelable: true })); });
      } else if (action === 'wait') {
        act(() => {});
      } else {
        throw new Error('unknown action: ' + String(action));
      }
      seen.push(dialogVisible(doc));
    }
    return seen;
  } finally {
    try { act(() => { root.unmount(); }); } catch (e) {}
    container.remove();
    doc.body.innerHTML = '';
  }
}

function main() {
  let ctx;
  try {
    ctx = setup();
  } catch (e) {
    emit({ results: [], harness_error: 'setup failed: ' + String((e && e.stack) || e) });
    return;
  }
  let inputs;
  try {
    inputs = JSON.parse(fs.readFileSync(path.join(__dirname, 'inputs.json'), 'utf8'));
  } catch (e) {
    emit({ results: [], harness_error: 'cannot read inputs.json: ' + String((e && e.message) || e) });
    return;
  }
  if (!Array.isArray(inputs)) {
    emit({ results: [], harness_error: 'inputs.json is not an array' });
    return;
  }
  const results = [];
  for (const item of inputs) {
    const id = item && item.id;
    try {
      results.push({ id, actual: runCase(ctx, item.input) });
    } catch (e) {
      results.push({ id, error: String((e && e.message) || e) });
    }
  }
  emit({ results });
}

main();
